// Classroom CRUD actions — AMD-converted from src/classroom_actions.js.
// @module     local_airpay_classroom/classroom_actions
// @copyright  2026 Airpay Payment Services
// @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
//
// 2026-05-20 — converted from ES6 to named AMD by hand. See sibling
// program_actions.min.js for the rationale. amd/src/ remains canonical ES6;
// behaviour changes must happen in BOTH places until Grunt is wired in.

define('local_airpay_classroom/classroom_actions', [
    'core_form/modalform',
    'core/str',
    'core/notification',
    'core/ajax'
], function(ModalForm, Str, Notification, Ajax) {
    'use strict';

    var getString = Str.get_string;

    var STATUS = {CANCELLED: 0, ACTIVE: 1, COMPLETED: 2};

    // ─── Classroom-level actions (existing — index.php) ───────────────────────

    var openClassroomForm = function(classroomid, returnFocus) {
        var titleKey = (classroomid === 0) ? 'addclassroom' : 'editclassroom';
        return getString(titleKey, 'local_airpay_classroom').then(function(title) {
            var modalForm = new ModalForm({
                formClass: 'local_airpay_classroom\\form\\edit_classroom',
                args: {classroomid: classroomid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || 'Saved.';
                Notification.addNotification({message: message, type: 'success'});
                window.location.reload();
            });
            modalForm.show();
        });
    };

    var confirmStatusChange = function(classroomid, name, newStatus, msgKey, returnFocus) {
        return getString('classroomstatuschanged', 'local_airpay_classroom').then(function(successMsg) {
            return Promise.all([
                getString(msgKey === 'confirmcancel' ? 'cancelclassroom' :
                          msgKey === 'confirmcomplete' ? 'completeclassroom' :
                          'reopenclassroom', 'local_airpay_classroom'),
                getString(msgKey, 'local_airpay_classroom', name)
            ]).then(function(strings) {
                var title = strings[0], message = strings[1];
                Notification.confirm(title, message, title, null, function() {
                    Ajax.call([{
                        methodname: 'local_airpay_classroom_change_status',
                        args: {classroomid: classroomid, status: newStatus}
                    }])[0].then(function() {
                        Notification.addNotification({message: successMsg, type: 'success'});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                });
                if (returnFocus) {
                    setTimeout(function() { returnFocus.focus(); }, 100);
                }
            });
        });
    };

    var confirmDelete = function(classroomid, name, returnFocus) {
        return Promise.all([
            getString('deleteclassroom', 'local_airpay_classroom'),
            getString('confirmdelete', 'local_airpay_classroom', name),
            getString('delete', 'core'),
            getString('classroomdeleted', 'local_airpay_classroom')
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], deleteLabel = strings[2], successMsg = strings[3];
            Notification.deleteCancelPromise(title, message, deleteLabel, returnFocus).then(function() {
                Ajax.call([{
                    methodname: 'local_airpay_classroom_delete_classroom',
                    args: {classroomid: classroomid}
                }])[0].then(function() {
                    Notification.addNotification({message: successMsg, type: 'success'});
                    window.location.reload();
                    return null;
                }).catch(Notification.exception);
                return true;
            }, function() { return null; });
        });
    };

    var handleClick = function(event) {
        var trigger = event.target.closest('[data-action]');
        if (!trigger) { return; }
        var action = trigger.dataset.action;
        var classroomid = parseInt(trigger.dataset.classroomid || '0', 10);
        var name = trigger.dataset.name || 'this classroom';
        switch (action) {
            case 'create-classroom':
                event.preventDefault();
                openClassroomForm(0, trigger);
                break;
            case 'edit-classroom':
                event.preventDefault();
                openClassroomForm(classroomid, trigger);
                break;
            case 'cancel-classroom':
                event.preventDefault();
                confirmStatusChange(classroomid, name, STATUS.CANCELLED, 'confirmcancel', trigger);
                break;
            case 'complete-classroom':
                event.preventDefault();
                confirmStatusChange(classroomid, name, STATUS.COMPLETED, 'confirmcomplete', trigger);
                break;
            case 'reopen-classroom':
                event.preventDefault();
                confirmStatusChange(classroomid, name, STATUS.ACTIVE, 'confirmreopen', trigger);
                break;
            case 'delete-classroom':
                event.preventDefault();
                confirmDelete(classroomid, name, trigger);
                break;
        }
    };

    // ─── View-page actions (G-02 — view.php sessions/users tabs) ──────────────

    var openSessionForm = function(classroomid, sessionid, returnFocus) {
        var titleKey = (sessionid === 0) ? 'add_session' : 'edit_session';
        return getString(titleKey, 'local_airpay_classroom').then(function(title) {
            var modalForm = new ModalForm({
                formClass: 'local_airpay_classroom\\form\\edit_session',
                args: {classroomid: classroomid, sessionid: sessionid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || 'Saved.';
                Notification.addNotification({message: message, type: 'success'});
                window.location.reload();
            });
            modalForm.show();
        });
    };

    var openEnrolUsersForm = function(classroomid, returnFocus) {
        return getString('enrol_users', 'local_airpay_classroom').then(function(title) {
            var modalForm = new ModalForm({
                formClass: 'local_airpay_classroom\\form\\enrol_classroom_users',
                args: {classroomid: classroomid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || 'Saved.';
                Notification.addNotification({message: message, type: 'success'});
                window.location.reload();
            });
            modalForm.show();
        });
    };

    // P1 #13 (2026-05-16) — bulk enrol by target audience.
    var openBulkEnrolAudienceForm = function(classroomid, returnFocus) {
        return getString('audience_modal_title', 'local_airpay_classroom').then(function(title) {
            var modalForm = new ModalForm({
                formClass: 'local_airpay_classroom\\form\\bulk_enrol_audience_form',
                args: {classroomid: classroomid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.LOADED, function() {
                var modalBody = document.querySelector('.modal.show .modal-body')
                    || document.querySelector('.modal-body');
                if (modalBody) {
                    require(['local_airpay_classroom/audience_form_helper'], function(helper) {
                        helper.init(modalBody);
                    });
                }
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var detail = event.detail || {};
                var enrolled = detail.enrolled || 0;
                var matched = detail.matched || 0;
                var message = enrolled === matched
                    ? 'Enrolled all ' + enrolled + ' matching user' + (enrolled === 1 ? '' : 's') + '.'
                    : enrolled + ' of ' + matched + ' matching users enrolled (rest were already enrolled).';
                Notification.addNotification({message: message, type: 'success'});
                window.location.reload();
            });
            modalForm.show();
        });
    };

    var confirmDeleteSession = function(sessionid, title, returnFocus) {
        return Promise.all([
            getString('delete_session', 'local_airpay_classroom'),
            getString('confirm_delete_session', 'local_airpay_classroom', title),
            getString('delete', 'core'),
            getString('sessiondeleted', 'local_airpay_classroom')
        ]).then(function(strings) {
            var confirmTitle = strings[0], message = strings[1], deleteLabel = strings[2], successMsg = strings[3];
            Notification.deleteCancelPromise(confirmTitle, message, deleteLabel, returnFocus).then(function() {
                Ajax.call([{
                    methodname: 'local_airpay_classroom_delete_session',
                    args: {sessionid: sessionid}
                }])[0].then(function() {
                    Notification.addNotification({message: successMsg, type: 'success'});
                    window.location.reload();
                    return null;
                }).catch(Notification.exception);
                return true;
            }, function() { return null; });
        });
    };

    var confirmUnenrolUser = function(classroomid, userid, name, returnFocus) {
        return Promise.all([
            getString('unenrol_user', 'local_airpay_classroom'),
            getString('confirm_unenrol_user', 'local_airpay_classroom', name),
            getString('remove', 'core'),
            getString('userunenrolled', 'local_airpay_classroom')
        ]).then(function(strings) {
            var confirmTitle = strings[0], message = strings[1], removeLabel = strings[2], successMsg = strings[3];
            Notification.deleteCancelPromise(confirmTitle, message, removeLabel, returnFocus).then(function() {
                Ajax.call([{
                    methodname: 'local_airpay_classroom_unenrol_user',
                    args: {classroomid: classroomid, userid: userid}
                }])[0].then(function() {
                    Notification.addNotification({message: successMsg, type: 'success'});
                    window.location.reload();
                    return null;
                }).catch(Notification.exception);
                return true;
            }, function() { return null; });
        });
    };

    var handleViewClick = function(classroomid) {
        return function(event) {
            var trigger = event.target.closest('[data-action]');
            if (!trigger) { return; }
            var action = trigger.dataset.action;
            switch (action) {
                case 'add-session':
                    event.preventDefault();
                    openSessionForm(classroomid, 0, trigger);
                    break;
                case 'edit-session': {
                    event.preventDefault();
                    var sid = parseInt(trigger.dataset.sessionid || '0', 10);
                    openSessionForm(classroomid, sid, trigger);
                    break;
                }
                case 'delete-session': {
                    event.preventDefault();
                    var sid2 = parseInt(trigger.dataset.sessionid || '0', 10);
                    var title = trigger.dataset.title || 'this session';
                    confirmDeleteSession(sid2, title, trigger);
                    break;
                }
                case 'enrol-users':
                    event.preventDefault();
                    openEnrolUsersForm(classroomid, trigger);
                    break;
                case 'bulk-enrol-audience':
                    event.preventDefault();
                    openBulkEnrolAudienceForm(classroomid, trigger);
                    break;
                case 'unenrol-user': {
                    event.preventDefault();
                    var uid = parseInt(trigger.dataset.userid || '0', 10);
                    var name = trigger.dataset.name || 'this user';
                    confirmUnenrolUser(classroomid, uid, name, trigger);
                    break;
                }
            }
        };
    };

    var init = function() {
        var root = document.querySelector('[data-region="airpay-classroom"]') || document.body;
        if (root.dataset.airpayClassroomInit === '1') { return; }
        root.dataset.airpayClassroomInit = '1';
        root.addEventListener('click', handleClick);
    };

    var initView = function(classroomid) {
        var root = document.querySelector('[data-region="airpay-classroom-view"]') || document.body;
        if (root.dataset.airpayClassroomViewInit === '1') { return; }
        root.dataset.airpayClassroomViewInit = '1';
        root.addEventListener('click', handleViewClick(classroomid));
    };

    return {
        init: init,
        initView: initView
    };
});
